//! The factory preset bank (PRESETS_PROMPT.md §7, VISION.md "Presets and the
//! browser"): the presets the browser, the in-instrument picker and the
//! device panel know, and the browser's library folders.
//!
//! Two sources, one list:
//! - **The bank** (`presets/bank.json`, generated by
//!   `presets/tools/design_bank.py`): the first bank, every preset designed
//!   from scratch with the macros, with its folder, voice, tags, an optional
//!   hardware profile (an **authentic** preset: Hardware, it locks the track)
//!   and its provenance.
//! - **The classic presets** (`chip::presets::PRESETS`, the 60 from Batch 1):
//!   folded into the bank in a "Classic" folder of their role (RUNLOG PB-D5),
//!   with their data unchanged.
//!
//! A preset **remembers its voice** (VISION.md "Instruments"): loading one on
//! a studio track switches the track to that voice. A classic preset suits
//! several voices (`kinds`), as before: a studio track already on one of them
//! keeps its voice.
//!
//! The library's whole-band presets (Hardware ▸ … ▸ Bands) are today's
//! channel layouts (`chip::presets::LAYOUTS`).

use std::sync::OnceLock;

use chip::driver::ParamId;
use chip::presets::{lane_kind, Category, LAYOUTS};
use chip::voice::VoiceKind;
use serde::Deserialize;

use crate::instruments::LaneInstrument;
use crate::state::{SoundChip, Unison};

/// The bank's text, built into the binary.
const BANK_JSON: &str = include_str!("../../../presets/bank.json");

/// Every factory preset is credited to him (VISION.md "Presets").
pub const AUTHOR: &str = "Jeffrey Scott Frederick";

/// One factory preset.
#[derive(Clone, Debug)]
pub struct Preset {
    pub name: String,
    /// Its library folder, from the section down ("Sounds", "Leads", "Square").
    pub path: Vec<String>,
    /// The Chip Synth voice (or the DPCM Sampler's) it is made for.
    pub voice: VoiceKind,
    /// The voices it suits (`chip::presets::K_*` bits): its own voice; a
    /// classic preset keeps its old set.
    pub kinds: u8,
    /// An authentic preset's hardware profile (it locks the track): the NES
    /// (2A03) or Famicom + VRC6.
    pub profile: Option<SoundChip>,
    /// Search tags: role, chip / voice, character.
    pub tags: Vec<String>,
    pub blurb: String,
    /// What the listening pack plays (`PHRASES`) and its octave shift.
    pub phrase: String,
    pub octave: i8,
    pub inst: LaneInstrument,
    /// Channel controls it sets (others keep their values).
    pub params: Vec<(ParamId, i8)>,
    /// Studio-only: Unison, Detune, Drift (the default: one voice, none).
    pub unison: Unison,
    pub author: String,
    pub date: String,
    /// The tool or source it came from.
    pub tool: String,
    /// One of the 60 classic presets (Batch 1), folded in.
    pub classic: bool,
}

impl Preset {
    /// Whether it plays on a voice type.
    pub fn fits_voice(&self, v: VoiceKind) -> bool {
        self.kinds & lane_kind(v.lane()) != 0
    }

    /// Whether it uses a studio-only control (Unison, Detune, Drift): it
    /// can't play on a locked track as it is.
    pub fn studio_only(&self) -> bool {
        self.unison != Unison::default()
    }

    pub fn authentic(&self) -> bool {
        self.profile.is_some()
    }

    /// Its folder as one string ("Sounds / Leads / Square").
    pub fn folder(&self) -> String {
        self.path.join(" / ")
    }

    /// Whether `query` (lowercase words) finds it: every word in its name,
    /// tags, blurb, folder or voice.
    pub fn matches(&self, words: &[String]) -> bool {
        let hay = format!("{} {} {} {} {}", self.name, self.tags.join(" "), self.blurb, self.path.join(" "), voice_name(self.voice)).to_lowercase();
        words.iter().all(|w| hay.contains(w.as_str()))
    }
}

/// A voice's name in the Voice selector and the Instruments folder.
pub fn voice_name(v: VoiceKind) -> &'static str {
    match v {
        VoiceKind::Pulse => "Pulse",
        VoiceKind::Triangle => "Triangle",
        VoiceKind::Noise => "Noise",
        VoiceKind::Dpcm => "DPCM",
        VoiceKind::Vrc6Pulse => "VRC6 Pulse",
        VoiceKind::Saw => "VRC6 Saw",
    }
}

/// The Chip Synth's voices, in the selector's order (VISION.md: Pulse ·
/// Triangle · Noise · VRC6 Pulse · VRC6 Saw); DPCM is the DPCM Sampler's.
pub const SYNTH_VOICES: [VoiceKind; 5] = [VoiceKind::Pulse, VoiceKind::Triangle, VoiceKind::Noise, VoiceKind::Vrc6Pulse, VoiceKind::Saw];

#[derive(Deserialize)]
struct BankFile {
    presets: Vec<Entry>,
}

#[derive(Deserialize)]
struct Entry {
    name: String,
    path: Vec<String>,
    voice: String,
    profile: Option<String>,
    tags: Vec<String>,
    blurb: String,
    phrase: String,
    #[serde(default)]
    octave: i8,
    instrument: serde_json::Value,
    #[serde(default)]
    params: std::collections::BTreeMap<String, i32>,
    #[serde(default)]
    unison: Option<[u8; 3]>,
    author: String,
    date: String,
    tool: String,
}

fn voice_of(key: &str) -> Result<VoiceKind, String> {
    Ok(match key {
        "pulse" => VoiceKind::Pulse,
        "triangle" => VoiceKind::Triangle,
        "noise" => VoiceKind::Noise,
        "dpcm" => VoiceKind::Dpcm,
        "vrc6_pulse" => VoiceKind::Vrc6Pulse,
        "saw" => VoiceKind::Saw,
        k => return Err(format!("unknown voice \"{k}\"")),
    })
}

/// The project-file key of a channel control.
pub fn param_key(p: ParamId) -> &'static str {
    match p {
        ParamId::Duty => "duty",
        ParamId::Volume => "volume",
        ParamId::Envelope => "envelope",
        ParamId::Sweep => "sweep",
        ParamId::SweepRate => "sweep_rate",
        ParamId::NoiseMode => "noise_mode",
        ParamId::NoisePeriod => "noise_period",
        ParamId::Sample => "sample",
        ParamId::Rate => "rate",
        ParamId::Loop => "loop",
    }
}

fn parse_entry(e: Entry) -> Result<Preset, String> {
    let voice = voice_of(&e.voice)?;
    let lane = voice.lane();
    let mut params = Vec::new();
    for (k, v) in &e.params {
        let id = ParamId::for_lane(lane).iter().copied().find(|p| param_key(*p) == k).ok_or_else(|| format!("{}: {} has no control \"{k}\"", e.name, voice_name(voice)))?;
        let (lo, hi, _) = id.range(lane);
        if !(lo..=hi).contains(v) {
            return Err(format!("{}: {k} {v} is outside {lo}..={hi}", e.name));
        }
        params.push((id, *v as i8));
    }
    let profile = match e.profile.as_deref() {
        None => None,
        Some("2A03") => Some(SoundChip::Base2A03),
        Some("VRC6") => Some(SoundChip::WithVrc6),
        Some(p) => return Err(format!("{}: unknown profile \"{p}\"", e.name)),
    };
    let u = e.unison.unwrap_or([1, 0, 0]);
    let inst = crate::file::instrument_from_json(e.instrument).map_err(|m| format!("{}: {m}", e.name))?;
    Ok(Preset {
        name: e.name,
        path: e.path,
        voice,
        kinds: lane_kind(lane),
        profile,
        tags: e.tags,
        blurb: e.blurb,
        phrase: e.phrase,
        octave: e.octave,
        inst,
        params,
        unison: Unison { voices: u[0].clamp(1, engine::studio::UNISON_MAX), detune: u[1].min(engine::studio::DETUNE_MAX), drift: u[2].min(engine::studio::DRIFT_MAX) },
        author: e.author,
        date: e.date,
        tool: e.tool,
        classic: false,
    })
}

/// A classic preset's folder: its role's "Classic" folder (RUNLOG PB-D5).
fn classic_path(p: &chip::presets::Preset) -> Vec<&'static str> {
    use Category::*;
    let role = match (p.category, p.name) {
        (Lead | Winds, _) => ["Sounds", "Leads"],
        (Bass, _) => ["Sounds", "Basses"],
        (Strings, "String Pad") | (Brass, "Horn Section") => ["Sounds", "Pads"],
        (Strings, "Pizzicato") => ["Sounds", "Bells & Keys"],
        (Strings | Brass, _) => ["Sounds", "Leads"],
        (Keys, _) => ["Sounds", "Bells & Keys"],
        (Chords, _) => ["Sounds", "Arps"],
        (Drums, _) => ["Drums", "Hits"],
        (Kits, _) => return vec!["Drums", "Kits"],
        (Sfx, "Coin" | "Jump" | "Power Up" | "1-Up" | "Menu Blip" | "Hit") => ["Sounds", "Game Sounds"],
        (Sfx, _) => ["Sounds", "FX"],
    };
    vec![role[0], role[1], "Classic"]
}

fn classic_phrase(p: &chip::presets::Preset) -> &'static str {
    use Category::*;
    match p.category {
        Lead | Winds | Brass | Strings => "lead",
        Bass => "bass",
        Keys => "keys",
        Chords => "arp",
        Drums if p.kinds == chip::presets::K_DMC && p.name == "Sample Kit" => "dpcm_map",
        Drums => "hit",
        Kits => "kit",
        Sfx if matches!(p.name, "Engine" | "Wind" | "Siren" | "Thunder") => "fx",
        Sfx => "game",
    }
}

/// The voice a classic preset is listed under: the first of its kinds in
/// the voices' order.
fn classic_voice(kinds: u8) -> VoiceKind {
    VoiceKind::ALL.into_iter().find(|v| kinds & lane_kind(v.lane()) != 0).unwrap_or(VoiceKind::Pulse)
}

fn classic(p: &chip::presets::Preset) -> Preset {
    let voice = classic_voice(p.kinds);
    let mut tags: Vec<String> = vec!["classic".into(), p.category.label().to_lowercase()];
    tags.extend(VoiceKind::ALL.iter().filter(|v| p.kinds & lane_kind(v.lane()) != 0).map(|v| voice_name(*v).to_lowercase()));
    Preset {
        name: p.name.into(),
        path: classic_path(p).into_iter().map(String::from).collect(),
        voice,
        kinds: p.kinds,
        profile: None,
        tags,
        blurb: p.blurb.into(),
        phrase: classic_phrase(p).into(),
        octave: 0,
        inst: LaneInstrument::from_preset(p),
        params: p.params.to_vec(),
        unison: Unison::default(),
        author: AUTHOR.into(),
        date: "2026-11-25".into(),
        tool: "crates/chip/src/presets.rs (written by hand, Batch 1)".into(),
        classic: true,
    }
}

/// Parses the bank text and folds in the classic presets.
pub fn parse(text: &str) -> Result<Vec<Preset>, String> {
    let f: BankFile = serde_json::from_str(text).map_err(|e| format!("presets/bank.json: {e}"))?;
    let mut out = Vec::with_capacity(f.presets.len() + chip::presets::PRESETS.len());
    for e in f.presets {
        out.push(parse_entry(e)?);
    }
    out.extend(chip::presets::PRESETS.iter().map(classic));
    for (i, a) in out.iter().enumerate() {
        if out[i + 1..].iter().any(|b| b.name.eq_ignore_ascii_case(&a.name)) {
            return Err(format!("two presets are named \"{}\"", a.name));
        }
    }
    Ok(out)
}

static BANK: OnceLock<Vec<Preset>> = OnceLock::new();

/// Every factory preset (the bank, then the classic ones).
pub fn all() -> &'static [Preset] {
    BANK.get_or_init(|| parse(BANK_JSON).expect("the built-in preset bank parses (bank::tests)"))
}

pub fn len() -> usize {
    all().len()
}

pub fn get(i: usize) -> Option<&'static Preset> {
    all().get(i)
}

/// A factory preset's index by name (any case).
pub fn index_of(name: &str) -> Option<usize> {
    let n = name.trim_end_matches('*');
    all().iter().position(|p| p.name.eq_ignore_ascii_case(n))
}

pub fn find(name: &str) -> Option<&'static Preset> {
    index_of(name).map(|i| &all()[i])
}

/// Puts factory preset `p` on track `lane`: its instrument and channel
/// controls; on a studio track also its voice (a preset remembers its voice;
/// a classic preset keeps a voice it suits) and its Unison / Detune / Drift.
/// A locked track keeps its channel (the caller checks the preset fits).
pub fn apply(a: &mut crate::state::Arrangement, lane: usize, p: &Preset) {
    let Some(t) = a.lanes.get(lane) else { return };
    let studio = t.lock.is_none();
    if studio && !p.fits_voice(t.voice) {
        a.set_voice(lane, p.voice);
    }
    a.instruments.set_lane(lane, p.inst.clone());
    let clips = a.clips.clone();
    a.instruments.prune(&clips);
    if let Some(l) = a.lanes.get_mut(lane) {
        let chan = l.chan();
        let mut row = engine::Params::default();
        row.values[chan] = l.params;
        for &(id, v) in &p.params {
            if ParamId::for_lane(chan).contains(&id) {
                row.set(chan, id, v as i32);
            }
        }
        l.params = row.values[chan];
        if studio {
            l.unison = p.unison;
        }
    }
}

// ───────────────────────────── The library's folders ─────────────────────────────

/// Something the browser lists.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Item {
    /// A factory preset (`all()[i]`).
    Preset(usize),
    /// A user preset (its index among the loaded user presets).
    User(usize),
    /// A whole-band preset (a channel layout, `LAYOUTS[i]`).
    Band(usize),
    /// A clip in the Clips folder (`PHRASES[i]`).
    Clip(usize),
    /// A DPCM sample: a built-in (0..4) or a project slot.
    Sample(usize),
    /// The "Import audio as DPCM…" row of the Samples folder.
    ImportAudio,
}

/// A folder: sub-folders first, then its items (Live's content pane).
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Folder {
    pub name: String,
    pub folders: Vec<Folder>,
    pub items: Vec<Item>,
}

impl Folder {
    fn new(name: &str) -> Self {
        Self { name: name.into(), ..Default::default() }
    }

    /// The folder at `path` below this one, made if missing.
    fn at(&mut self, path: &[String]) -> &mut Folder {
        let Some((first, rest)) = path.split_first() else { return self };
        let i = match self.folders.iter().position(|f| &f.name == first) {
            Some(i) => i,
            None => {
                self.folders.push(Folder::new(first));
                self.folders.len() - 1
            }
        };
        self.folders[i].at(rest)
    }

    /// Every item in this folder and below.
    pub fn count(&self) -> usize {
        self.items.len() + self.folders.iter().map(Folder::count).sum::<usize>()
    }

    /// Every item, depth first (folders before items, as listed).
    pub fn flatten(&self) -> Vec<Item> {
        let mut v: Vec<Item> = self.folders.iter().flat_map(Folder::flatten).collect();
        v.extend(self.items.iter().copied());
        v
    }

    /// The folder holding `item` directly, and its path from here.
    pub fn parent_of(&self, item: Item) -> Option<(Vec<String>, &Folder)> {
        if self.items.contains(&item) {
            return Some((Vec::new(), self));
        }
        for f in &self.folders {
            if let Some((mut p, g)) = f.parent_of(item) {
                p.insert(0, f.name.clone());
                return Some((p, g));
            }
        }
        None
    }

    /// The sub-folder at `path`.
    pub fn find(&self, path: &[String]) -> Option<&Folder> {
        let Some((first, rest)) = path.split_first() else { return Some(self) };
        self.folders.iter().find(|f| &f.name == first)?.find(rest)
    }
}

/// The library's static sections (Sounds, Drums, Instruments, Hardware,
/// Clips), built once. Samples, the User Library and the Current Project
/// change with the project and the user's files: the browser builds them.
pub struct Library {
    pub sounds: Folder,
    pub drums: Folder,
    pub instruments: Folder,
    pub hardware: Folder,
    pub clips: Folder,
}

/// The order of the role folders (VISION.md's list).
const SOUND_ORDER: [&str; 7] = ["Leads", "Basses", "Arps", "Pads", "Bells & Keys", "FX", "Game Sounds"];

fn order_folders(f: &mut Folder, order: &[&str]) {
    f.folders.sort_by_key(|g| {
        let pos = order.iter().position(|o| *o == g.name).unwrap_or(order.len());
        // "Classic" (the old library) after the new folders.
        (pos, g.name == "Classic")
    });
}

fn build() -> Library {
    let mut root = Folder::new("");
    for (i, p) in all().iter().enumerate() {
        if p.authentic() {
            continue;
        }
        root.at(&p.path).items.push(Item::Preset(i));
    }
    let mut sounds = root.folders.iter().find(|f| f.name == "Sounds").cloned().unwrap_or_else(|| Folder::new("Sounds"));
    order_folders(&mut sounds, &SOUND_ORDER);
    for f in &mut sounds.folders {
        order_folders(f, &[]);
    }
    let mut drums = root.folders.iter().find(|f| f.name == "Drums").cloned().unwrap_or_else(|| Folder::new("Drums"));
    order_folders(&mut drums, &["Kits", "Hits"]);
    for f in &mut drums.folders {
        order_folders(f, &["Noise", "Triangle", "Samples"]);
    }
    // Hardware: the authentic presets by profile and channel, and the bands.
    let mut hardware = Folder::new("Hardware");
    for (i, p) in all().iter().enumerate().filter(|(_, p)| p.authentic()) {
        hardware.at(&p.path[1..]).items.push(Item::Preset(i));
    }
    for (i, l) in LAYOUTS.iter().enumerate() {
        let prof = if l.vrc6 { "Famicom + VRC6" } else { "NES (2A03)" };
        hardware.at(&[prof.to_string(), "Bands".to_string()]).items.push(Item::Band(i));
    }
    order_folders(&mut hardware, &["NES (2A03)", "Famicom + VRC6"]);
    for f in &mut hardware.folders {
        order_folders(f, &["Pulse", "Triangle", "Noise", "DPCM", "VRC6 Pulse", "VRC6 Saw", "Bands"]);
    }
    // Instruments: the two instruments, then each voice's presets.
    let mut instruments = Folder::new("Instruments");
    let mut synth = Folder::new("Chip Synth");
    for v in SYNTH_VOICES {
        let mut f = Folder::new(voice_name(v));
        f.items = all().iter().enumerate().filter(|(_, p)| p.voice == v).map(|(i, _)| Item::Preset(i)).collect();
        synth.folders.push(f);
    }
    let mut dpcm = Folder::new("DPCM Sampler");
    dpcm.items = all().iter().enumerate().filter(|(_, p)| p.voice == VoiceKind::Dpcm).map(|(i, _)| Item::Preset(i)).collect();
    instruments.folders = vec![synth, dpcm];
    let mut clips = Folder::new("Clips");
    clips.items = (0..PHRASES.len()).map(Item::Clip).collect();
    Library { sounds, drums, instruments, hardware, clips }
}

static LIBRARY: OnceLock<Library> = OnceLock::new();

pub fn library() -> &'static Library {
    LIBRARY.get_or_init(build)
}

/// The folder a preset is browsed in (its own; an authentic preset's is
/// under Hardware), and its path from the section.
pub fn home_of(i: usize) -> Option<(Vec<String>, &'static Folder)> {
    let lib = library();
    let p = get(i)?;
    let (section, name) = if p.authentic() { (&lib.hardware, "Hardware") } else if p.path.first().is_some_and(|s| s == "Drums") { (&lib.drums, "Drums") } else { (&lib.sounds, "Sounds") };
    section.parent_of(Item::Preset(i)).map(|(mut path, f)| {
        path.insert(0, name.to_string());
        (path, f)
    })
}

/// The presets of a preset's own folder, in order (◀ ▶ step through these).
pub fn siblings(i: usize) -> Vec<usize> {
    home_of(i).map_or_else(Vec::new, |(_, f)| f.items.iter().filter_map(|it| if let Item::Preset(p) = it { Some(*p) } else { None }).collect())
}

/// The preset after (`+1`) or before (`-1`) `i` in its folder, wrapping.
pub fn step(i: usize, dir: i32) -> Option<usize> {
    let s = siblings(i);
    let k = s.iter().position(|&p| p == i)?;
    let n = s.len() as i32;
    Some(s[((k as i32 + dir).rem_euclid(n)) as usize])
}

