/// A short phrase: (name, the role it shows off, notes as (start beat,
/// length in beats, MIDI pitch)). The Clips folder lists them; the listening
/// pack plays each preset its role's phrase. All written for this bank.
pub struct Phrase {
    pub name: &'static str,
    pub role: &'static str,
    pub bars: u32,
    pub notes: &'static [(f32, f32, u8)],
}

